(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.017-t*0.28)*16+Math.sin(x*0.015+t*0.33)*11;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8+Math.cos(sy*0.02+t*0.35)*6;
  const w2y = Math.cos(sy*0.023+t*0.38)*7+Math.sin(sx*0.019-t*0.42)*5;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.075,2.1,0.8],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.09,1.8,1.0],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.055,2.4,0.7],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.11,1.6,1.1],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.065,2.7,0.9],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.085,2.0,0.85],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.1,1.4,1.2],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*55,0.07,2.2,0.75],
    [200+Math.sin(t*0.25)*110,220+Math.cos(t*0.45+2)*70,0.095,1.9,0.95]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    wS+=Math.sin(d*f*1.3-t*sp*0.4+0.8)*w*0.5;
  }
  const tw=src.reduce((a,s)=>a+s[4],0);
  const act=aS/tw,inh=iS/tw,wav=wS/tw;
  const n1=Math.sin(fx*0.038+fy*0.024+t*0.9);
  const n2=Math.sin(fx*0.028-fy*0.038+t*1.2);
  const n3=Math.sin((fx+fy)*0.015+t*0.6);
  const bg=(n1+n2)*0.35+n3*0.3;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.6);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.3);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.1)*0.5;
  const spiral=(sp1+sp2)*0.35+sp3;
  const pulse=Math.sin(dist*0.02-t*0.8)*0.3;
  let r1=act-inh*0.65+bg*0.25+spiral*0.3+pulse;
  r1-=0.15*Math.sin(fx*0.12+t*1.5)*Math.sin(fy*0.1-t*1.2);
  r1+=wav*0.2;
  const r2=Math.tanh(r1*1.8);
  const r3=Math.tanh(r2*1.5+r1*0.4);
  const cell=Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.4+Math.sin(fx*0.08-fy*0.11+t*0.7)*0.3)*1.3)*0.25;
  const voro=(()=>{
    let md=99;
    for(let i=0;i<7;i++){
      const vx=80+i*55+Math.sin(t*0.4+i*1.7)*25;
      const vy=40+((i*37)%200)+Math.cos(t*0.35+i*2.1)*20;
      md=Math.min(md,Math.sqrt((fx-vx)**2+(fy-vy)**2));
    }
    return Math.tanh((md-15)*0.15)*0.2;
  })();
  const blend=r3*0.6+cell*0.25+voro*0.15;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,95],[15,95,120],[25,155,145],[180,190,60],[215,140,55],[195,80,65],[120,35,70],[50,15,55],[5,12,52]];
  const idx=v*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2);
  const f=idx-i;
  const edge=Math.abs(r3)>0.6?1.0+Math.abs(r3)*0.2:1.0;
  const glow=Math.max(0,Math.abs(r3)-0.5)*0.4;
  const lum=0.82+Math.sin(r3*Math.PI)*0.18+glow;
  const breathe=0.95+Math.sin(t*0.3)*0.05;
  const L=lum*edge*breathe;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*L+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*L+glow*25)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*L+glow*15)|0)
  ];
}
